    processed_ignore_unpinned_requirements = ignore_unpinned_requirements
    processed_project = project

    if policy_file:
        security = policy_file.get('security', {})

        if not ignore:
            processed_ignore = security.get('ignore-vulnerabilities', {})

        if not ignore_severity_rules:
